#!/usr/bin/env python3
"""Expand campaign leases into canary and low-IID /128 targets."""
import argparse
import hashlib
import ipaddress
import random
import sys


def _canary(seed, lease_id, network):
    material = (seed + '\n' + lease_id + '\n' + network).encode('utf-8')
    return int.from_bytes(hashlib.sha256(material).digest()[:8], 'big') | (1 << 63)


def plan(leases, seed):
    """Return (manifest, probes, low) for every lease in the campaign."""
    manifest = []
    probes = {}
    low = {}
    for lease_id in sorted(leases):
        lease = leases[lease_id]
        table = {}
        lows = set()
        for subnet in lease['subnets']:
            base = int(lease['network'].network_address) + (subnet << 64)
            network = str(ipaddress.IPv6Network((base, 64)))
            canary = _canary(seed, lease_id, network)
            rows = [('c', canary)] + [('i%d' % i, i) for i in range(1, lease['low_count'] + 1)]
            for slot, value in rows:
                target = base + value
                probe = '%d/%s' % (subnet, slot)
                manifest.append({'lease': lease_id, 'probe': probe,
                                 'target': str(ipaddress.IPv6Address(target))})
                table[probe] = (target, slot == 'c')
                if slot != 'c':
                    lows.add(target)
        probes[lease_id] = table
        low[lease_id] = lows
    return manifest, probes, low


def random_iid() -> str:
    h = "%016x" % random.getrandbits(64)
    return ":".join(h[i:i + 4] for i in range(0, 16, 4))


def format_iid(value: int) -> str:
    h = "%016x" % value
    return ":".join(h[i:i + 4] for i in range(0, 16, 4))


def main() -> None:
    parser = argparse.ArgumentParser(description="expand IPv6 prefixes into probe targets")
    parser.add_argument("input_file", help="IPv6 prefixes, one per line")
    parser.add_argument("output_file", help="file to write targets to")
    parser.add_argument("num_targets", type=int, help="sequential low IIDs per prefix")
    parser.add_argument("--canary", help="canary IID (default: random per run)")
    args = parser.parse_args()

    if args.num_targets < 1:
        parser.error("num_targets must be at least 1")
    if args.num_targets >= (1 << 64):
        parser.error("num_targets is too large")

    canary = args.canary or random_iid()
    print(f"canary IID: {canary}", file=sys.stderr)

    with open(args.input_file) as infile, open(args.output_file, "w") as outfile:
        for line in infile:
            prefix = line.strip()
            if not prefix:
                continue
            outfile.write(f"{prefix}:{canary}\n")
            for i in range(1, args.num_targets + 1):
                outfile.write(f"{prefix}:{format_iid(i)}\n")


if __name__ == "__main__":
    main()
